var l = ["<script", ' type="application/ld+json">', "<\/script>"], p = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], g = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>NACE HIC Steel Plates Guide</span></div>'], u = ["<main", ' style="', '"><div style="', '"><span style="', '">Safety Critical</span><span style="', '">June 2026 \xB7 9 min read</span><h1 style="', '">NACE HIC Steel Plates \u2014 Essential for Sour Service Environments</h1><p style="', `">In oil and gas processing, equipment failure in sour (H\u2082S-containing) service doesn't just mean downtime \u2014 it means potential explosion, toxic gas release, and loss of life. <strong>NACE HIC steel plates</strong> are specifically engineered to resist hydrogen-induced cracking in these lethal environments. As India's trusted <strong>NACE HIC steel plate supplier</strong> and <strong>carbon steel SA 516 plate stockist</strong>, Creative Metal Industries supplies HIC-tested plates with complete documentation for the country's most critical refinery and offshore projects.</p></div><h2 style="`, '">What is NACE HIC and Why It Matters for Oil &amp; Gas</h2><p style="', '"><strong>NACE</strong> refers to NACE International (now AMPP) standard MR-01-75 (current version: ANSI/NACE MR0175/ISO 15156), which defines material requirements for metallic equipment used in H\u2082S-containing (sour) oil and gas production environments. It mandates hardness limits, heat treatment conditions, and specific testing to prevent catastrophic in-service failures.</p><p style="', '"><strong>HIC</strong> stands for Hydrogen Induced Cracking \u2014 a specific failure mechanism where atomic hydrogen (generated by corrosion in H\u2082S environments) diffuses into steel and accumulates at manganese sulphide (MnS) inclusions, creating internal blisters and cracks that propagate parallel to the plate surface. Unlike mechanical fatigue, HIC requires zero applied stress \u2014 even unstressed plates in storage can crack if manufactured from susceptible material.</p><h2 style="', '">Hydrogen Induced Cracking \u2014 The Mechanism Explained</h2><ol style="', '"><li><strong>Corrosion reaction:</strong> H\u2082S in the process fluid attacks the steel surface: Fe + H\u2082S \u2192 FeS + 2H\u2070 (atomic hydrogen)</li><li><strong>Hydrogen absorption:</strong> Atomic hydrogen (H\u2070) is tiny \u2014 it diffuses directly into the steel lattice</li><li><strong>Hydrogen trapping:</strong> H atoms accumulate at planar inclusion sites (elongated MnS stringers from rolling)</li><li><strong>Molecular recombination:</strong> H\u2070 + H\u2070 \u2192 H\u2082 (molecular hydrogen gas) at the inclusion interface</li><li><strong>Pressure build-up:</strong> H\u2082 molecules cannot diffuse back out \u2014 internal pressure builds to thousands of atmospheres</li><li><strong>Crack initiation:</strong> Internal pressure exceeds local yield \u2014 a blister/crack forms parallel to the rolling direction</li><li><strong>Crack linking:</strong> Adjacent cracks connect through the thickness via stepwise cracking (SOHIC) \u2192 through-wall failure</li></ol><h2 style="', '">Chemical Requirements for HIC Resistance</h2><p style="', '">HIC-resistant plates require fundamentally different steelmaking than standard SA 516:</p><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Parameter</th><th style="', '">Standard SA 516 Gr.70</th><th style="', '">HIC-Resistant SA 516 Gr.70</th><th style="', '">Why</th></tr></thead><tbody>', '</tbody></table></div><h2 style="', '">Key Applications \u2014 Where NACE HIC Plates are Mandatory</h2><div style="', '">', '</div><h2 style="', '">Testing and Certification Standards</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Test</th><th style="', '">Standard</th><th style="', '">Acceptance Criteria</th></tr></thead><tbody>', '</tbody></table></div><h2 style="', '">Why Source NACE HIC Plates from Creative Metal Industries?</h2><ul style="', `"><li><strong>Specialist stockist:</strong> We maintain dedicated HIC-tested stock separate from standard plates \u2014 SA 516 Gr.60/70, SA 537 Cl.1/2, SA 387 Gr.11/22 in NACE/HIC condition</li><li><strong>Complete test documentation:</strong> Every plate comes with HIC test report (TM-0284) showing CLR, CTR, CSR values per specimen, plus SSC report (TM-0177) on request</li><li><strong>Tighter acceptance available:</strong> Some clients (Shell, ONGC) require CLR \u2264 10%, CTR \u2264 3% \u2014 we source plates meeting these stricter criteria from AMNS and TATA</li><li><strong>Approved mills:</strong> AMNS (ArcelorMittal Nippon Steel), TATA Steel, SAIL (Bokaro HIC line), and imported plates from POSCO, Dillinger</li><li><strong>Third-party inspection:</strong> DNV GL, TUV SUD, Bureau Veritas, Lloyd's inspection at our Vadodara facility before dispatch</li><li><strong>Also stocking:</strong> Standard <a href="/carbon-steel-sa516-plate-stockist-india" style="`, '">SA 516 plates</a>, <a href="/tmt-bars-supplier-gujarat" style="', '">TMT bars</a>, and structural steel as a complete <strong>steel trading company in Gujarat</strong></li></ul><h2 style="', '">Frequently Asked Questions \u2014 NACE HIC Plates</h2><div style="', '">', '</div><div style="', '"><h2 style="', '">Need NACE HIC Tested Plates?</h2><p style="', '">SA 516, SA 387, API 5L \u2014 all in HIC condition. Complete TM-0284 + TM-0177 reports. AMNS, TATA mills.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/nace-hic-steel-plate-supplier-india" style="', '">View Stock & Grades \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], h = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 NACE HIC Steel Plate Supplier India | Carbon Steel Stockist | Gujarat</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], f = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], y = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], C = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], A = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
const S = JSON.stringify({ "@context": "https://schema.org", "@type": "Article", headline: "NACE HIC Steel Plates \u2014 Essential for Sour Service Environments", author: { "@type": "Organization", name: "Creative Metal Industries" }, publisher: { "@type": "Organization", name: "Creative Metal Industries", logo: { "@type": "ImageObject", url: "https://www.creativemetalind.com/logo_cmi.png" } }, datePublished: "2026-06-17", image: "https://www.creativemetalind.com/img/carbon-steel-plate.webp", url: "https://www.creativemetalind.com/blog/nace-hic-steel-plates-guide" }), H = JSON.stringify({ "@context": "https://schema.org", "@type": "FAQPage", mainEntity: [{ "@type": "Question", name: "What does NACE HIC mean?", acceptedAnswer: { "@type": "Answer", text: "NACE refers to NACE MR-01-75 (now ANSI/NACE MR0175/ISO 15156) \u2014 a standard specifying material requirements for sour (H\u2082S-containing) environments. HIC means Hydrogen Induced Cracking \u2014 internal cracking caused by atomic hydrogen diffusing into steel and recombining at inclusion sites. NACE HIC plates are specifically manufactured with ultra-low sulphur, calcium treatment, and controlled rolling to resist this failure mechanism." } }, { "@type": "Question", name: "When do I need NACE HIC plates?", acceptedAnswer: { "@type": "Answer", text: "NACE HIC plates are required when equipment will contain fluids with H\u2082S partial pressure exceeding 0.05 psi (0.3 kPa) \u2014 the threshold defined in NACE MR-01-75. This includes: sour gas separators, amine absorbers/regenerators, sour water strippers, crude oil storage with H\u2082S, desulphurisation units, and any vessel/pipeline handling wet H\u2082S in oil & gas refineries." } }, { "@type": "Question", name: "What are the HIC test acceptance criteria?", acceptedAnswer: { "@type": "Answer", text: "Per NACE TM-0284 (standard test method): CLR (Crack Length Ratio) \u2264 15%, CTR (Crack Thickness Ratio) \u2264 5%, CSR (Crack Sensitivity Ratio) \u2264 2%. Test conditions: specimens immersed in Solution A (5% NaCl + 0.5% CH\u2083COOH, saturated with H\u2082S) for 96 hours at 25\xB0C, then ultrasonically examined for internal cracks." } }] });
